/* Page-based local preview for source questionnaires, using the frozen sim definition. */
const pageStepRenderSim=renderSim;
function pageQuestionPath(definition,answers){const map=new Map(definition.nodes.map(n=>[n.id,n])),seen=new Set(),questions=[];let id=definition.entryNodeId;while(id&&!seen.has(id)){seen.add(id);const n=map.get(id);if(!n)break;if(n.type==='question'){questions.push(n);id=n.next}else if(n.type==='condition'){const checks=[n,...(n.clauses||[])].map(c=>compare(answers[c.source],c.op,c.value));id=(n.match==='any'?checks.some(Boolean):checks.every(Boolean))?n.yes:n.no}else if(n.type==='end')break;else id=n.next}return questions}
function pagePruneHidden(run){let visible=[];for(let i=0;i<run.nodes.length+1;i++){visible=pageQuestionPath(run.definition,run.answers);const ids=new Set(visible.map(q=>q.id));let changed=false;for(const bucket of ['answers','otherAnswers','pageFiles'])for(const id of Object.keys(run[bucket]||{}))if(!ids.has(id)){delete run[bucket][id];changed=true}if(!changed)break}for(const q of visible){const v=run.answers[q.id];if(!(Array.isArray(v)?v.includes('other'):v==='other'))delete run.otherAnswers?.[q.id]}return visible}
function pageGroups(run){const visible=pagePruneHidden(run),groups=[];for(const q of visible){const key=q.sourcePage||'additional';let g=groups.find(p=>p.key===key);if(!g){g={key,title:q.sourcePageTitle||'Additional questions',scope:q.sourceScope||'animal',questions:[]};groups.push(g)}g.questions.push(q)}return run.pageScope?groups.filter(g=>g.scope===run.pageScope):groups}
function pageInputValue(run,id){return run.answers[id]??''}
function pageQuestionError(q,run){const value=run.answers[q.id],empty=value===undefined||value===null||value===''||(Array.isArray(value)&&value.length===0);if(empty)return q.required===false?'':'Answer this question.';if(q.answer==='Number'){const n=Number(value);if(!Number.isFinite(n))return 'Enter a valid number.';if(q.min!=null&&n<q.min)return 'Minimum: '+q.min+(q.unit?' '+q.unit:'');if(q.max!=null&&n>q.max)return 'Maximum: '+q.max+(q.unit?' '+q.unit:'')}if(['Single choice','Multiple choice','Yes / No'].includes(q.answer)){const opts=q.answer==='Yes / No'?['Yes','No']:questionnaireOptions(q).map(o=>String(o.value)),values=Array.isArray(value)?value:[value];if(values.some(v=>!opts.includes(String(v))))return 'Choose an available answer.'}if(q.answer==='Catalogue'&&!(run.definition.catalogues[q.id]||[]).some(i=>i.id===value))return 'Choose an item from this snapshot.';if(q.allowOther&&(Array.isArray(value)?value.includes('other'):value==='other')&&!run.otherAnswers?.[q.id]?.trim())return 'Describe the Other answer.';if(['Photo','Video','Photo or video'].includes(q.answer)){const p=questionProofSettings(q),files=run.pageFiles?.[q.id]||[],min=Math.max(1,q.proofRequiredMin||p.minFiles||1);if(files.length<min||files.length>p.maxFiles)return `Choose ${min} to ${p.maxFiles} files.`;if(files.some(f=>f.type&&!p.accepts.some(a=>f.type.startsWith(a==='photo'?'image/':'video/'))))return 'Only the configured photo/video types are allowed.'}return ''}
function pageSetAnswer(id,value){if(!sim?.pageMode)return;const before=pageQuestionPath(sim.definition,sim.answers).map(q=>q.id).join('|');sim.answers[id]=value;sim.pageErrors??={};delete sim.pageErrors[id];const after=pagePruneHidden(sim).map(q=>q.id).join('|');if(before!==after||Array.isArray(value)||sim.nodes.find(q=>q.id===id)?.allowOther)renderPagePreview();else{const el=document.getElementById('page-error-'+id);if(el)el.textContent=''}}
function pageSelectFiles(id,input){if(!sim?.pageMode)return;const files=Array.from(input.files||[]).map(f=>({name:f.name,type:f.type,size:f.size}));sim.pageFiles??={};sim.pageFiles[id]=files;sim.answers[id]=files.map(f=>f.name);renderPagePreview()}
function pageClearFiles(id){delete sim.pageFiles?.[id];delete sim.answers[id];renderPagePreview()}
function pageMultiAnswer(id,value,checked){const current=Array.isArray(sim.answers[id])?sim.answers[id]:[];pageSetAnswer(id,checked?[...new Set([...current,value])]:current.filter(v=>v!==value))}
function pageField(q){const value=pageInputValue(sim,q.id),selectedValues=Array.isArray(value)?value:[],inputId='page-answer-'+q.id;let control='';if(['Single choice','Yes / No'].includes(q.answer)){const opts=q.answer==='Yes / No'?[{value:'Yes',label:'Yes'},{value:'No',label:'No'}]:questionnaireOptions(q);control=`<select id="${inputId}" aria-label="${esc(q.label)}" onchange="pageSetAnswer('${q.id}',this.value)"><option value="">Choose an answer…</option>${opts.map(o=>`<option value="${esc(o.value)}" ${String(value)===String(o.value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`}else if(q.answer==='Multiple choice')control=questionnaireOptions(q).map((o,i)=>`<label class="page-check"><input type="checkbox" ${selectedValues.includes(o.value)?'checked':''} data-choice-value="${esc(o.value)}" onchange="pageMultiAnswer('${q.id}',this.dataset.choiceValue,this.checked)">${esc(o.label)}</label>`).join('');else if(q.answer==='Catalogue')control=`<select id="${inputId}" aria-label="${esc(q.label)}" onchange="pageSetAnswer('${q.id}',this.value)"><option value="">Choose an item…</option>${(sim.definition.catalogues[q.id]||[]).map(i=>`<option value="${esc(i.id)}" ${value===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select><small>Choices come from this run’s frozen catalogue.</small>`;else if(['Photo','Video','Photo or video'].includes(q.answer)){const p=questionProofSettings(q),files=sim.pageFiles?.[q.id]||[];control=`<input id="${inputId}" aria-label="${esc(q.label)}" type="file" ${p.maxFiles>1?'multiple':''} accept="${p.accepts.map(a=>a==='photo'?'image/*':'video/*').join(',')}" onchange="pageSelectFiles('${q.id}',this)"><small>${p.accepts.map(esc).join(' or ')} · max ${p.maxFiles} · local file names only</small>${files.length?`<div class="page-file-list">${files.map(f=>`<span>${esc(f.name)}</span>`).join('')}<button onclick="pageClearFiles('${q.id}')">Clear files</button></div>`:''}`}else control=`<input id="${inputId}" aria-label="${esc(q.label)}" type="${q.answer==='Number'?'number':q.answer==='Date'?'date':'text'}" ${q.answer==='Number'?'step="any"':''} ${q.min!=null?`min="${q.min}"`:''} ${q.max!=null?`max="${q.max}"`:''} value="${esc(value)}" oninput="pageSetAnswer('${q.id}',this.value)">${q.answer==='Number'?`<small>${q.unit?esc(q.unit)+' · ':''}${q.min!=null?'min '+q.min:''}${q.max!=null?' · max '+q.max:''}</small>`:''}`;const other=q.allowOther&&(Array.isArray(value)?value.includes('other'):value==='other');return `<section class="page-question" id="page-question-${q.id}"><label class="page-question-title" for="${inputId}">${esc(q.label)} ${q.required===false?'<span>Optional</span>':'<b>*</b>'}</label>${q.hint?`<p>${esc(q.hint)}</p>`:''}${control}${other?`<label class="field page-other"><span>Please specify</span><input aria-label="Other details for ${esc(q.label)}" value="${esc(sim.otherAnswers?.[q.id]||'')}" oninput="sim.otherAnswers??={};sim.otherAnswers['${q.id}']=this.value"></label>`:''}<div class="error" id="page-error-${q.id}">${esc(sim.pageErrors?.[q.id]||'')}</div></section>`}
function pageMove(direction){const groups=pageGroups(sim);let index=groups.findIndex(g=>g.key===sim.pageKey);if(direction>0){const errors={};for(const q of groups[index].questions){const error=pageQuestionError(q,sim);if(error)errors[q.id]=error}if(Object.keys(errors).length){sim.pageErrors=errors;renderPagePreview();document.getElementById('page-question-'+Object.keys(errors)[0])?.scrollIntoView({block:'center'});return}}index=Math.max(0,Math.min(groups.length-1,index+direction));sim.pageKey=groups[index].key;sim.pageErrors={};renderPagePreview();document.querySelector('.page-preview-body')?.scrollTo(0,0)}
function pageSubmit(){const groups=pageGroups(sim);for(const g of groups){const errors={};for(const q of g.questions){const error=pageQuestionError(q,sim);if(error)errors[q.id]=error}if(Object.keys(errors).length){sim.pageKey=g.key;sim.pageErrors=errors;renderPagePreview();document.getElementById('page-question-'+Object.keys(errors)[0])?.scrollIntoView({block:'center'});return}}sim.pageComplete=true;renderPagePreview()}
function renderPagePreview(){const groups=pageGroups(sim);if(!groups.length)return;const previous=sim.pageOrder||groups.map(g=>g.key);if(!groups.some(g=>g.key===sim.pageKey)){const old=previous.indexOf(sim.pageKey);sim.pageKey=previous.slice(0,Math.max(0,old)).reverse().find(k=>groups.some(g=>g.key===k))||groups[0].key}sim.pageOrder=groups.map(g=>g.key);const index=groups.findIndex(g=>g.key===sim.pageKey),g=groups[index];$('#overlay').innerHTML=`<div class="modalbg"><section class="modal page-preview"><div class="modalhead"><div><h2>${esc(sim.title)}</h2><span class="muted">${esc(sim.mode)} · Page preview · No live actions</span></div><button onclick="closeModal()" aria-label="Close page preview">✕</button></div><div class="page-preview-body"><div class="page-scope-tabs"><button class="${sim.pageScope==='animal'?'primary':''}" onclick="pageChangeScope('animal')">One animal inspection</button><button class="${sim.pageScope==='load'?'primary':''}" onclick="pageChangeScope('load')">Load details</button><button onclick="pageRunFullGraph()">Run full graph ↗</button></div>${sim.nodes.some(n=>n.type==='action')?'<div class="notice">Question pages test answers and visibility. Use Run full graph to test your authored actions and outcomes.</div>':''}${sim.pageComplete?`<div class="notice"><h2>Preview complete</h2><p>${Object.keys(sim.answers).length} visible answers captured in this local test. Nothing was submitted.</p></div><button onclick="sim.pageComplete=false;sim.pageKey=pageGroups(sim)[0].key;renderPagePreview()">Review answers</button><details><summary>Captured local answers</summary><pre>${esc(JSON.stringify({answers:sim.answers,other:sim.otherAnswers},null,2))}</pre></details>`:`<div class="page-stepper">${groups.map((p,i)=>`<span class="${i===index?'active':''}">${i+1}. ${esc(p.title)}</span>`).join('')}</div><div class="page-scope-note">${g.scope==='load'?'Load details · collected once for a load.':'Animal inspection · this preview follows one animal; repeat these pages for each animal.'}</div><h2>${esc(g.title)}</h2><p class="muted">Page ${index+1} of ${groups.length} · ${g.questions.length} visible questions</p>${g.questions.map(pageField).join('')}`}</div><div class="page-preview-footer"><button onclick="startSim()">Restart preview</button><div class="spacer"></div>${!sim.pageComplete?`<button onclick="pageMove(-1)" ${index===0?'disabled':''}>← Previous page</button><button class="primary" onclick="${index===groups.length-1?'pageSubmit()':'pageMove(1)'}">${index===groups.length-1?'Complete preview':'Next page →'}</button>`:''}</div></section></div>`}
function pageChangeScope(scope){sim.pageScope=scope;sim.pageComplete=false;sim.pageErrors={};sim.pageKey=pageGroups(sim)[0]?.key;renderPagePreview()}
function pageRunFullGraph(){sim.pageSaved={answers:structuredClone(sim.answers),otherAnswers:structuredClone(sim.otherAnswers||{}),pageFiles:structuredClone(sim.pageFiles||{}),pageKey:sim.pageKey,pageScope:sim.pageScope};sim.forceStep=true;sim.pageMode=false;sim.answers={};sim.otherAnswers={};sim.path=[];sim.id=sim.definition.entryNodeId;const entry=sim.nodes.find(n=>n.id===sim.id);if(entry?.type==='start')sim.id=entry.next;renderSim()}
function pageReturnToQuestions(){Object.assign(sim,sim.pageSaved||{});sim.forceStep=false;sim.pageMode=true;sim.pageComplete=false;renderPagePreview()}
renderSim=function(){if(sim?.definition?.nodes.some(n=>n.sourcePage)){if(!sim.forceStep){if(!sim.pageMode){sim.pageMode=true;sim.pageScope='animal';sim.pageKey='identity';sim.pageErrors={};sim.pageFiles={};sim.otherAnswers={}}return renderPagePreview()}pageStepRenderSim();const head=document.querySelector('.modalhead');if(head&&!head.querySelector('.return-question-pages'))head.insertAdjacentHTML('afterend','<button class="return-question-pages" onclick="pageReturnToQuestions()">← Return to question pages (keep page answers)</button>');return}return pageStepRenderSim()};
